{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "EBS volume encryption not enabled",
      "resource": "aws_ami.pass",
      "severity": "HIGH",
      "explanation": "The EBS block device '/dev/xvda1' does not have encryption enabled. Unencrypted volumes can expose sensitive data if compromised."
    }
  ],
  "patched_code": "resource "aws_ami" "pass" {
  name                = "terraform-example"
  virtualization_type = "hvm"
  root_device_name    = "/dev/xvda1"

  ebs_block_device {
    device_name = "/dev/xvda1"
    volume_size = 8
    snapshot_id = "someid"
    encrypted   = true
  }

  ebs_block_device {
    device_name = "/dev/xvda2"
    volume_size = 8
    encrypted   = true
  }
}
",
  "fix_summary": "Enabled encryption for the EBS block device '/dev/xvda1' to ensure data at rest is protected."
}
